api.look('agent');
const cx = api.w/2, cy = 300;
const k = api.seg(t, 0, 1.2);
api.rect(cx-70, cy-120, 140, 240, {r:24, c:'fg', w:4, k});
api.rect(cx-58, cy-100, 116, 190, {r:10, c:'dim', w:2, k:api.seg(t,0.4,1.4)});
api.circle(cx, cy+104, 7, {c:'fg', w:3, k:api.seg(t,0.8,1.4)});
api.shape('speech', cx, cy-20, 60, {c:'accent', w:4, k:api.seg(t,1,2)});
api.swarm(20, t, {mode:'rise', cx, cy:cy-130, rx:60, ry:40, c:'a2', size:3});
api.text('Your phone', cx, cy+170, {size:28, c:'fg', align:'center', k:api.seg(t,1.5,2.5)});
api.focus(cx, cy, api.lerp(1, 1.15, api.ease(api.seg(t,1,3.5))));
api.say('A message starts here', 0.3, 3.3);

api.look('agent');
const names = ['Phone app','Gateway','Agent','Model','Database'];
const icons = ['phone','lock','person','bulb','flask'];
const x = api.w/2, w = 220, h = 70, top = 90, gap = 120;
const N = [];
for (let i = 0; i < 5; i++) {
  const p = api.stag(t, i, {gap:0.5, dur:0.6, from:0.1});
  N.push(api.node(x, top + i*gap, w, h, names[i], {icon:icons[i], k:p, pop:true, c: i===2 ? 'accent' : 'a2'}));
}
for (let i = 0; i < 4; i++) {
  api.link(N[i], N[i+1], {k:api.seg(t, 0.6+i*0.5, 1.2+i*0.5), flow:t});
}
api.say('Five parts, one chain', 0.3, 5.5);

api.look('agent');
const names = ['Phone app','Gateway','Agent','Model','Database'];
const icons = ['phone','lock','person','bulb','flask'];
const x = api.w/2, w = 220, h = 70, top = 90, gap = 120;
const N = [];
for (let i = 0; i < 5; i++) N.push(api.node(x, top + i*gap, w, h, names[i], {icon:icons[i], k:1, c: i===2 ? 'accent' : 'a2'}));
for (let i = 0; i < 4; i++) api.link(N[i], N[i+1], {k:1, c:'dim'});
const prog = api.seg(t, 0.4, 5.2);
const y = top + prog*4*gap;
api.glow(x, y, 40, {c:'accent'});
api.dot(x, y, 12, {c:'accent'});
const stop = Math.min(4, Math.floor(prog*4+0.5));
api.label(['Hello!','Checked','Plan made','Asked','Saved'][stop], x+w/2+20, y, {k:1});
api.say('Your message goes down', 0.4, 5.6);

api.look('agent');
const names = ['Phone app','Gateway','Agent','Model','Database'];
const icons = ['phone','lock','person','bulb','flask'];
const x = api.w/2, w = 220, h = 70, top = 90, gap = 120;
const N = [];
for (let i = 0; i < 5; i++) N.push(api.node(x, top + i*gap, w, h, names[i], {icon:icons[i], k:1, c: i===3 ? 'a3' : 'a2'}));
for (let i = 0; i < 4; i++) api.link(N[i], N[i+1], {k:1, c:'dim'});
const prog = api.seg(t, 0.4, 4.6);
const y = top + 3*gap - prog*3*gap;
api.glow(x, y, 40, {c:'good'});
api.dot(x, y, 12, {c:'good'});
api.label(prog > 0.95 ? 'Reply!' : 'Answer', x+w/2+20, y, {k:1});
api.say('The answer comes back up', 0.4, 5.6);

api.look('agent');
const cx = api.w/2, cy = 300;
api.rect(cx-70, cy-120, 140, 240, {r:24, c:'fg', w:4});
api.rect(cx-58, cy-100, 116, 190, {r:10, c:'dim', w:2});
api.shape('check', cx, cy-10, 80, {c:'good', w:6, k:api.seg(t,0.2,1.2)});
api.text('Reply arrives', cx, cy+170, {size:30, c:'fg', align:'center', k:api.seg(t,0.8,1.8)});
api.swarm(40, t, {mode:'burst', cx, cy:cy-10, rx:120, ry:120, c:'good', size:3});
api.focus(cx, cy, api.lerp(1.2, 1, api.ease(api.seg(t,0,3))));
api.say('Phone to model and back', 0.4, 4.6);
